import data from "./proofs.generated.json";

export type ProofLink = { label: string; url: string; layer?: string };
export type ProofEntry = {
  id: string;
  title: string;
  summary: string;
  checks: Array<{ name: string; pass: boolean }>;
  links: ProofLink[];
  facts: Record<string, string>;
};
export type GateEntry = { gate: string; name: string; status: string; decision: string };

/** Generated by `pnpm proofs` from docs/proofs. */
export const proofs = data as unknown as { entries: ProofEntry[]; gates: GateEntry[] };

export const explorerAddress = (address: string) =>
  `https://explorer.solana.com/address/${address}?cluster=devnet`;
